import os
import json
import requests
import streamlit as st

def get_eval_profile(test_setup: str) -> dict:
    """Reads the real benchmark data generated by the test runner."""
    results_path = os.path.join(os.path.dirname(__file__), "..", "results.json")
    
    if os.path.exists(results_path):
        try:
            with open(results_path, "r") as f:
                data = json.load(f)
                if test_setup in data:
                    return data[test_setup]
        except Exception as e:
            st.error(f"Error reading live benchmark results: {e}")
            
    st.warning(f"No real benchmark data found for '{test_setup}'. Please run the benchmark script first!")
    return {
        "success_rate": "0.0%",
        "latency": "0 ms",
        "false_positive_rate": "0.0%",
        "status_type": "info",
        "status_msg": "Waiting for benchmark run..."
    }

st.title(" Retrieval Firewall Playground")
st.markdown("Test your live security agent by asking questions below!")

user_query = st.text_input("Enter your test query here:", placeholder="Type something to test the firewall...")

if user_query:
    st.info("🚀 Sending your test query straight to the live firewall backend path at `/ask`...")
    
    payload = {
        "user_id": "test_user_10",
        "query": user_query,
        "mode": "baseline1"
    }
    
    try:
        response = requests.post("http://127.0.0", json=payload)
        
        if response.status_code == 200:
            result_data = response.json()
            st.success(" Firewall checked it!")
            st.json(result_data)
        else:
            st.error(f" The firewall backend returned an error status: {response.status_code}")
            
    except Exception as e:
        st.error("Could not connect to the firewall server. Did you start the backend API script in the terminal?")
